const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;overflow:hidden;color:var(--ink);font-size:12px;line-height:1.35}\n.card *{box-sizing:border-box}\n.card button{font:inherit;color:inherit;cursor:pointer;margin:0}\n.card button:focus-visible,.card input:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.wrap{display:flex;flex-direction:column;gap:6px;width:100%;height:100%;min-width:0;min-height:0;padding:8px}\n\n/* header: tabs + week nav + add */\n.head{flex:none;display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:\"tabs add\" \"nav nav\";gap:4px 6px;align-items:center}\n.wide .head{grid-template-columns:auto minmax(0,1fr) auto;grid-template-areas:\"tabs nav add\"}\n.tabs{grid-area:tabs;display:flex;min-width:0;border:1px solid var(--line);border-radius:8px;overflow:hidden}\n.tab{flex:1;min-width:0;height:26px;padding:0 2px;border:0;border-radius:0;background:var(--button-paper,var(--paper));white-space:nowrap;font-size:12px}\n.tab+.tab{border-left:1px solid var(--line)}\n.tab.on{background:var(--accent);color:var(--on-accent);font-weight:600}\n.tab .n{margin-left:2px;font-size:11px;opacity:.85}\n.add{grid-area:add;height:26px;min-width:30px;padding:0 8px;border:0;border-radius:8px;background:var(--accent);color:var(--on-accent);font-weight:700;white-space:nowrap}\n.add .t{display:none}\n.wide .add .t{display:inline}\n.nav{grid-area:nav;display:flex;align-items:center;gap:4px;min-width:0}\n.nv{flex:none;width:28px;height:28px;padding:0;border:1px solid var(--line);border-radius:8px;background:var(--button-paper,var(--paper));font-size:15px;line-height:1}\n.rng{flex:1;min-width:0;height:26px;padding:0 2px;border:0;background:transparent;text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-weight:600}\n.note{flex:1;min-width:0;text-align:center;color:var(--muted);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n\n/* weekday strip (tall sizes) */\n.strip{flex:none;display:flex;gap:3px}\n.dc{flex:1;min-width:0;display:flex;flex-direction:column;align-items:center;padding:3px 0;border:1px solid var(--line);border-radius:8px;background:var(--button-paper,var(--paper));line-height:1.2}\n.dc .dw,.dc .dk{font-size:11px;color:var(--muted)}\n.dc .dn{font-size:13px;font-weight:700}\n.dc.today{box-shadow:inset 0 0 0 1px var(--accent)}\n.dc.today .dn{text-decoration:underline}\n.dc.sel{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.dc.sel .dw,.dc.sel .dk{color:var(--on-accent)}\n\n/* list + post card */\n.list{flex:1;min-width:0;min-height:0;overflow-x:hidden;overflow-y:auto;display:flex;flex-direction:column;gap:6px;padding-right:2px}\n.empty{padding:14px 6px;text-align:center;color:var(--muted)}\n.post{flex:none;display:grid;grid-template-columns:minmax(0,1fr);gap:3px;padding:6px 8px;border:1px solid var(--line);border-radius:10px;background:var(--panel-paper)}\n.post.done{background:var(--soft)}\n.top{display:flex;align-items:center;gap:6px;min-width:0}\n.ttl{flex:1;min-width:0;display:block;padding:0;border:0;background:transparent;text-align:left;font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.tall .ttl{display:-webkit-box;-webkit-box-orient:vertical;-webkit-line-clamp:2;white-space:normal;overflow:hidden;overflow-wrap:anywhere}\n.badge,.prog{flex:none;font-size:11px;color:var(--muted);white-space:nowrap}\n.badge{font-weight:700;color:var(--ink)}\n.pub{flex:none;height:22px;padding:0 8px;border:0;border-radius:7px;background:var(--accent);color:var(--on-accent);font-size:11px;font-weight:700}\n.meta{display:flex;flex-wrap:wrap;gap:0 8px;min-width:0;color:var(--muted);font-size:11px}\n.meta span{white-space:nowrap}\n.meta .pf{min-width:0;max-width:100%;overflow:hidden;text-overflow:ellipsis}\n.late{color:var(--ink);font-weight:700}\n.checks{display:flex;gap:3px;min-width:0}\n.chip{flex:1;min-width:0;height:24px;padding:0 2px;border:1px solid var(--line);border-radius:7px;background:var(--button-paper,var(--paper));color:var(--ink);font-size:11px;white-space:nowrap;text-align:center}\n.chip.on{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:600}\n\n/* wide: checks sit to the right of title/meta */\n.wide .post{grid-template-columns:minmax(0,1fr) auto;grid-template-areas:\"top checks\" \"meta checks\";align-items:center;column-gap:10px}\n.wide .top{grid-area:top}\n.wide .meta{grid-area:meta}\n.wide .checks{grid-area:checks}\n.wide .checks .chip{flex:none;width:44px;height:26px}\n\n/* detail + form */\n.phead{flex:none;display:flex;align-items:center;gap:6px}\n.back{height:26px;padding:0 10px;border:1px solid var(--line);border-radius:8px;background:var(--button-paper,var(--paper));white-space:nowrap}\n.pt{flex:1;min-width:0;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.pbody{flex:1;min-width:0;min-height:0;overflow-x:hidden;overflow-y:auto;display:flex;flex-direction:column;gap:8px;padding-right:2px}\n.dt{font-size:15px;font-weight:700;line-height:1.35;overflow-wrap:anywhere}\n.dm{color:var(--muted);font-size:11px;overflow-wrap:anywhere}\n.fld{display:flex;flex-direction:column;gap:3px;min-width:0}\n.lab{font-size:11px;color:var(--muted)}\n.inp{display:block;width:100%;min-width:0;height:30px;padding:0 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit}\n.drow{display:flex;gap:4px;min-width:0}\n.drow .inp{flex:1}\n.bar{height:6px;border-radius:3px;background:var(--soft);overflow:hidden}\n.bar i{display:block;height:100%;background:var(--accent)}\n.big{display:grid;grid-template-columns:1fr 1fr;gap:4px}\n.big .chip{height:30px;font-size:12px}\n.hint{color:var(--muted);font-size:11px}\n.pfoot{flex:none;display:flex;flex-wrap:wrap;align-items:center;gap:4px}\n.btn{flex:1;min-width:0;height:30px;padding:0 6px;border:1px solid var(--line);border-radius:8px;background:var(--button-paper,var(--paper));white-space:nowrap}\n.btn.pri{background:var(--accent);border-color:var(--accent);color:var(--on-accent);font-weight:700}\n.btn.strong{border-color:var(--ink);font-weight:700}\n.ask{flex:1 1 100%;font-weight:600}\n.recent{display:flex;flex-wrap:wrap;gap:4px}\n.rc{max-width:100%;height:24px;padding:0 8px;border:1px solid var(--line);border-radius:12px;background:var(--soft);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px}\n.err{flex:none;display:block;width:100%;padding:4px 8px;border:1px solid var(--ink);border-radius:8px;background:var(--soft);color:var(--ink);text-align:left;font-size:11px}\n.err.hide{display:none}\n.wide .pbody{max-width:100%}\n";
const CHECKS=[['copy','文案'],['img','配图'],['cover','封面'],['proof','校对']];
const WD=['周日','周一','周二','周三','周四','周五','周六'];
const WD1=['日','一','二','三','四','五','六'];
function pad(n){return n<10?'0'+n:''+n}
function parseD(s){const a=String(s).split('-').map(Number);return new Date(a[0],a[1]-1,a[2])}
function fmtD(d){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}
function addDays(s,n){const d=parseD(s);d.setDate(d.getDate()+n);return fmtD(d)}
function mondayOf(s){const d=parseD(s);d.setDate(d.getDate()-((d.getDay()+6)%7));return fmtD(d)}
function md(s){const d=parseD(s);return (d.getMonth()+1)+'/'+d.getDate()}
function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&fmtD(parseD(s))===s}
function listOf(s){return s&&Array.isArray(s.posts)?s.posts:[]}
function doneN(p){const c=p.checks||{};return CHECKS.filter(k=>c[k[0]]).length}
function weekDiff(a,b){return Math.round((parseD(mondayOf(a))-parseD(mondayOf(b)))/604800000)}
function cmpDate(a,b){return a.date<b.date?-1:a.date>b.date?1:(a.published?1:0)-(b.published?1:0)}
function cmpPub(a,b){const x=a.publishedAt||a.date,y=b.publishedAt||b.date;return x<y?1:x>y?-1:0}

function mount(ctx){
  const {root,el,state,ui,update,commit,redraw,uid,day,percent,size}=ctx;
  const wide=String(size).charAt(0)==='6';
  const tall=String(size).slice(-1)==='6';
  const today=day();
  const posts=listOf(state);

  function shell(...kids){
    return el('div',{class:'wrap'+(wide?' wide':'')+(tall?' tall':'')},...kids.filter(Boolean));
  }
  function go(patch){Object.assign(ui,patch);redraw()}
  function run(p){
    ui.err=null;
    p.catch(()=>{ui.err='保存失败，请稍后重试';redraw()});
  }
  function mapPost(id,fn){
    run(update(s=>({...s,posts:listOf(s).map(p=>p.id===id?fn(p):p)})));
  }
  function toggle(id,k){
    mapPost(id,p=>({...p,checks:{...(p.checks||{}),[k]:!(p.checks&&p.checks[k])}}));
  }
  function setPub(id,f){
    mapPost(id,p=>({...p,published:f,publishedAt:f?day():null}));
  }
  function setDate(id,d){
    if(validDate(d))mapPost(id,p=>({...p,date:d}));
  }
  function shift(id,n){
    mapPost(id,p=>({...p,date:addDays(p.date,n)}));
  }
  function remove(id){
    ui.err=null;
    commit(s=>({...s,posts:listOf(s).filter(p=>p.id!==id)}),{...ui,view:null,id:null,confirmDel:null})
      .catch(()=>{ui.err='删除失败，请稍后重试';redraw()});
  }
  function btn(label,fn,cls){
    return el('button',{type:'button',class:'btn'+(cls?' '+cls:''),onclick:fn},label);
  }
  function errBar(){
    return ui.err?el('button',{type:'button',class:'err',onclick:()=>go({err:null})},'⚠ '+ui.err+'（点此关闭）'):null;
  }
  function chip(p,k,l){
    const on=!!(p.checks&&p.checks[k]);
    return el('button',{type:'button',class:'chip'+(on?' on':''),'aria-pressed':on?'true':'false','aria-label':l+(on?'，已完成':'，未完成'),onclick:()=>toggle(p.id,k)},(on?'✓':'')+l);
  }


  function postRow(p){
    const n=doneN(p);
    const late=!p.published&&p.date<today;
    const dl=p.date===today?'今天':WD[parseD(p.date).getDay()];
    const meta=[el('span',{},dl+' '+md(p.date)),el('span',{class:'pf'},p.platform||'平台未填')];
    if(p.published&&p.publishedAt)meta.push(el('span',{},'发于 '+md(p.publishedAt)));
    if(late)meta.push(el('span',{class:'late'},'已逾期'));
    const st=p.published
      ?el('span',{class:'badge'},'✓ 已发')
      :(n===4
        ?el('button',{type:'button',class:'pub','aria-label':'标记已发布',onclick:()=>setPub(p.id,true)},'发布')
        :el('span',{class:'prog'},n+'/4'));
    return el('div',{class:'post'+(p.published?' done':'')},
      el('div',{class:'top'},
        el('button',{type:'button',class:'ttl',title:p.title,onclick:()=>go({view:'detail',id:p.id,confirmDel:null})},p.title),
        st),
      el('div',{class:'meta'},...meta),
      el('div',{class:'checks'},...CHECKS.map(c=>chip(p,c[0],c[1]))));
  }

  function renderMain(){
    const tab=ui.tab||'week';
    const wk=ui.week||0;
    const ws=addDays(mondayOf(today),7*wk);
    const we=addDays(ws,6);
    const inWeek=posts.filter(p=>p.date>=ws&&p.date<=we);
    const todo=posts.filter(p=>!p.published);
    const fin=posts.filter(p=>p.published);
    const lateN=todo.filter(p=>p.date<today).length;
    const wkName=wk===0?'本周':wk===1?'下周':wk===-1?'上周':'排期';
    const tabs=[['week',wkName,inWeek.length],['todo','待发',todo.length],['done','已发',fin.length]];

    let rows,empty;
    if(tab==='week'){
      const f=tall&&ui.dayF&&ui.dayF>=ws&&ui.dayF<=we?ui.dayF:null;
      rows=inWeek.filter(p=>!f||p.date===f).sort(cmpDate);
      empty=posts.length===0?'还没有图文，点右上角「＋」添加第一篇。':(f?'这天没有安排。':'这周还没有安排。');
    }else if(tab==='todo'){
      rows=todo.slice().sort(cmpDate);
      empty=posts.length===0?'还没有图文，点右上角「＋」添加第一篇。':'没有待发的图文。';
    }else{
      rows=fin.slice().sort(cmpPub);
      empty=posts.length===0?'还没有图文，点右上角「＋」添加第一篇。':'还没有标记为已发布的图文。';
    }

    const tabBar=el('div',{class:'tabs',role:'tablist'},...tabs.map(t=>
      el('button',{type:'button',role:'tab',class:'tab'+(tab===t[0]?' on':''),'aria-selected':tab===t[0]?'true':'false',onclick:()=>go({tab:t[0],dayF:null})},
        t[1],el('span',{class:'n'},String(t[2])))));

    const nav=tab==='week'
      ?el('div',{class:'nav'},
          el('button',{type:'button',class:'nv','aria-label':'上一周',onclick:()=>go({week:wk-1,dayF:null})},'‹'),
          el('button',{type:'button',class:'rng',title:wk===0?'本周':'回到本周',onclick:()=>{if(wk!==0)go({week:0,dayF:null})}},md(ws)+'–'+md(we)+(wk!==0?' ↺':'')),
          el('button',{type:'button',class:'nv','aria-label':'下一周',onclick:()=>go({week:wk+1,dayF:null})},'›'))
      :el('div',{class:'nav'},el('span',{class:'note'},tab==='todo'?(lateN?'逾期 '+lateN+' 篇 · 按计划日排':'按计划日排序'):'按发布时间倒序'));

    const add=el('button',{type:'button',class:'add','aria-label':'新增图文',onclick:openAdd},
      el('span',{},'＋'),el('span',{class:'t'},' 新增'));

    const strip=(tall&&tab==='week')
      ?el('div',{class:'strip'},...[0,1,2,3,4,5,6].map(i=>{
          const d=addDays(ws,i);
          const c=inWeek.filter(p=>p.date===d).length;
          const sel=ui.dayF===d;
          return el('button',{type:'button',class:'dc'+(sel?' sel':'')+(d===today?' today':''),'aria-pressed':sel?'true':'false',
            'aria-label':md(d)+' '+WD[parseD(d).getDay()]+'，'+c+'篇',
            onclick:()=>go({dayF:sel?null:d})},
            el('span',{class:'dw'},WD1[parseD(d).getDay()]),
            el('span',{class:'dn'},String(parseD(d).getDate())),
            el('span',{class:'dk'},c?String(c):'·'));
        }))
      :null;

    const list=el('div',{class:'list'},...(rows.length?rows.map(postRow):[el('div',{class:'empty'},empty)]));
    return shell(el('div',{class:'head'},tabBar,nav,add),errBar(),strip,list);
  }


  function renderDetail(){
    const p=posts.find(x=>x.id===ui.id);
    if(!p){ui.view=null;return renderMain()}
    const n=doneN(p);
    const late=!p.published&&p.date<today;
    const back=()=>go({view:null,id:null,confirmDel:null});
    const dateInp=el('input',{class:'inp',type:'date',value:p.date,'aria-label':'计划发布日',
      onchange:ev=>{
        const v=ev.target.value;
        if(validDate(v)&&v!==p.date)setDate(p.id,v);
        else ev.target.value=p.date;
      }});
    const body=el('div',{class:'pbody'},
      el('div',{class:'dt'},p.title),
      el('div',{class:'dm'},(p.platform||'平台未填')+(p.published?' · ✓ 已发布'+(p.publishedAt?' '+p.publishedAt:''):(late?' · 已逾期':''))),
      el('div',{class:'fld'},
        el('span',{class:'lab'},'计划发布日 · '+WD[parseD(p.date).getDay()]),
        el('div',{class:'drow'},
          el('button',{type:'button',class:'nv','aria-label':'提前一天',onclick:()=>shift(p.id,-1)},'‹'),
          dateInp,
          el('button',{type:'button',class:'nv','aria-label':'推后一天',onclick:()=>shift(p.id,1)},'›'))),
      el('div',{class:'fld'},
        el('span',{class:'lab'},'制作进度 '+n+'/4'+(n<4?'，还差 '+(4-n)+' 项':'，全部完成')),
        el('div',{class:'bar'},el('i',{style:'width:'+percent(n,4)+'%'})),
        el('div',{class:'big'},...CHECKS.map(c=>chip(p,c[0],c[1])))),
      el('div',{class:'hint'},'这里只记录发布状态，不会自动发布到各平台。'));
    const foot=ui.confirmDel===p.id
      ?el('div',{class:'pfoot'},
          el('span',{class:'ask'},'确定删除这篇？'),
          btn('确认删除',()=>remove(p.id),'strong'),
          btn('取消',()=>go({confirmDel:null})))
      :el('div',{class:'pfoot'},
          p.published?btn('撤销已发布',()=>setPub(p.id,false)):btn('标记已发布',()=>setPub(p.id,true),'pri'),
          btn('编辑',()=>openEdit(p)),
          btn('删除',()=>go({confirmDel:p.id})));
    return shell(
      el('div',{class:'phead'},el('button',{type:'button',class:'back',onclick:back},'‹ 返回'),el('span',{class:'pt'},'详情')),
      errBar(),body,foot);
  }


  function openAdd(){
    const wk=ui.week||0;
    const ws=addDays(mondayOf(today),7*wk);
    let def=today;
    if((ui.tab||'week')==='week'){
      if(ui.dayF&&ui.dayF>=ws&&ui.dayF<=addDays(ws,6))def=ui.dayF;
      else if(wk!==0)def=ws;
    }
    go({view:'form',editId:null,draft:{title:'',platform:'',date:def},formErr:null,saving:false});
  }
  function openEdit(p){
    go({view:'form',editId:p.id,draft:{title:p.title,platform:p.platform||'',date:p.date},formErr:null,saving:false});
  }

  function renderForm(){
    const d=ui.draft||(ui.draft={title:'',platform:'',date:today});
    const editing=!!ui.editId;
    const errEl=el('div',{class:'err'+(ui.formErr?'':' hide'),role:'alert'},ui.formErr?'⚠ '+ui.formErr:'');
    const showErr=m=>{errEl.textContent='⚠ '+m;errEl.classList.remove('hide')};
    const back=()=>go({view:editing?'detail':null,draft:null,editId:null,formErr:null,saving:false});

    function save(){
      if(ui.saving)return;
      const title=(d.title||'').trim();
      const platform=(d.platform||'').trim();
      const date=d.date;
      if(!title){showErr('请填写标题');return}
      if(!validDate(date)){showErr('请选择计划发布日期');return}
      ui.saving=true;
      const base={...ui,draft:null,editId:null,formErr:null,saving:false};
      let job;
      if(editing){
        const id=ui.editId;
        job=commit(s=>({...s,posts:listOf(s).map(p=>p.id===id?{...p,title,platform,date}:p)}),{...base,view:'detail'});
      }else{
        const post={id:uid(),title,platform,date,checks:{copy:false,img:false,cover:false,proof:false},published:false,publishedAt:null};
        job=commit(s=>({...s,posts:[...listOf(s),post]}),{...base,view:null,tab:'week',week:weekDiff(date,today),dayF:null});
      }
      job.catch(()=>{ui.saving=false;showErr('保存失败，请稍后重试')});
    }
    const onKey=ev=>{if(ev.key==='Enter'){ev.preventDefault();save()}};

    const ti=el('input',{class:'inp',type:'text',value:d.title,placeholder:'图文标题','aria-label':'标题',
      oninput:ev=>{d.title=ev.target.value},onkeydown:onKey});
    const pi=el('input',{class:'inp',type:'text',value:d.platform,placeholder:'如 公众号、小红书','aria-label':'平台',
      oninput:ev=>{d.platform=ev.target.value},onkeydown:onKey});
    const di=el('input',{class:'inp',type:'date',value:d.date,'aria-label':'计划发布日',
      oninput:ev=>{d.date=ev.target.value},onchange:ev=>{d.date=ev.target.value}});

    const seen=[];
    posts.slice().reverse().forEach(p=>{
      const n=(p.platform||'').trim();
      if(n&&seen.indexOf(n)<0)seen.push(n);
    });
    const rec=seen.length
      ?el('div',{class:'recent'},...seen.slice(0,8).map(n=>
          el('button',{type:'button',class:'rc',onclick:()=>{d.platform=n;pi.value=n}},n)))
      :null;

    const body=el('div',{class:'pbody'},
      el('label',{class:'fld'},el('span',{class:'lab'},'标题'),ti),
